const configRows = $('Read Config').all();
const cfg = {};
for (const r of configRows) {
  if (r.json.key) cfg[r.json.key] = r.json.value;
}

const queriesPerRun = parseInt(cfg.queries_per_run || '3', 10);
const minReviews = parseInt(cfg.min_review_count || '3', 10);
let cityIndex = parseInt(cfg.city_index || '0', 10);
let categoryIndex = parseInt(cfg.category_index || '0', 10);

const cities = [
  { name: 'Victoria', region: 'CRD' },
  { name: 'Saanich', region: 'CRD' },
  { name: 'Langford', region: 'West Shore' },
  { name: 'Nanaimo', region: 'Central Island' },
  { name: 'Duncan', region: 'Cowichan Valley' },
  { name: 'Courtenay', region: 'Comox Valley' },
  { name: 'Campbell River', region: 'North Island' },
  { name: 'Sidney', region: 'Saanich Peninsula' },
  { name: 'Sooke', region: 'West Shore' },
  { name: 'Parksville', region: 'Central Island' },
  { name: 'Ladysmith', region: 'Cowichan Valley' },
  { name: 'Colwood', region: 'West Shore' },
  { name: 'Oak Bay', region: 'CRD' },
  { name: 'Esquimalt', region: 'CRD' },
  { name: 'Qualicum Beach', region: 'Central Island' },
  { name: 'Port Alberni', region: 'Central Island' },
  { name: 'Comox', region: 'Comox Valley' }
];

const categories = [
  { id: 'music_store', query: 'music store' },
  { id: 'diesel_repair', query: 'diesel repair' },
  { id: 'auto_repair', query: 'auto repair shop' },
  { id: 'plumber', query: 'plumber' },
  { id: 'electrician', query: 'electrician' },
  { id: 'hvac', query: 'HVAC contractor' },
  { id: 'bike_shop', query: 'bicycle shop' },
  { id: 'marine', query: 'marine supply' },
  { id: 'veterinarian', query: 'veterinarian' },
  { id: 'bakery', query: 'bakery' },
  { id: 'landscaping', query: 'landscaping company' },
  { id: 'roofing', query: 'roofing contractor' },
  { id: 'dentist', query: 'dentist' },
  { id: 'pet_grooming', query: 'pet grooming' },
  { id: 'furniture_store', query: 'furniture store' }
];

const existingIds = new Set(
  $('Read Existing Prospects').all()
    .map(i => (i.json.place_id || '').toString())
    .filter(Boolean)
);

const queue = [];
for (let i = 0; i < queriesPerRun; i++) {
  const city = cities[cityIndex % cities.length];
  const cat = categories[categoryIndex % categories.length];
  queue.push({
    text_query: `${cat.query} in ${city.name} BC`,
    category_id: cat.id,
    city_name: city.name,
    region: city.region,
    min_review_count: minReviews,
    existing_place_ids: [...existingIds],
    next_city_index: (cityIndex + 1) % cities.length,
    next_category_index: (categoryIndex + 1) % categories.length
  });
  categoryIndex++;
  if (categoryIndex % categories.length === 0) cityIndex++;
}

return queue.map(j => ({ json: j }));

const meta = $('Build Search Queue').item.json;
const places = $input.first().json.places || [];
const existing = new Set(meta.existing_place_ids || []);
const minReviews = meta.min_review_count || 3;

const out = [];
for (const p of places) {
  const website = p.websiteUri;
  if (!website) continue;
  const reviews = p.userRatingCount || 0;
  if (reviews < minReviews) continue;
  const placeId = (p.id || '').replace(/^places\//, '');
  if (!placeId || existing.has(placeId)) continue;
  existing.add(placeId);

  out.push({
    place_id: placeId,
    business_name: p.displayName?.text || '',
    address: p.formattedAddress || '',
    phone: p.nationalPhoneNumber || '',
    website,
    google_maps_url: p.googleMapsUri || '',
    category: meta.category_id,
    city: meta.city_name,
    region: meta.region,
    google_rating: p.rating ?? '',
    review_count: reviews,
    next_city_index: meta.next_city_index,
    next_category_index: meta.next_category_index
  });
}

if (out.length === 0) {
  return [{ json: { _empty: true, message: 'No new prospects with websites for this query' } }];
}
return out.map(j => ({ json: j }));

const prospect = $('Limit Per Run').item.json;
const mobileRaw = $('PageSpeed Mobile').first().json;
const desktopRaw = $('PageSpeed Desktop').first().json;
const fetch = $('Fetch Homepage').first().json;

const parsePs = (d) => {
  const s = d?.lighthouseResult?.categories?.performance?.score;
  return s == null ? null : Math.round(s * 100);
};

const mobile = parsePs(mobileRaw);
const desktop = parsePs(desktopRaw);

const statusCode = fetch.statusCode || fetch.status || 0;
const html = typeof fetch.body === 'string' ? fetch.body : (fetch.data || '');
const website = prospect.website || '';
const hasHttps = website.startsWith('https://');
const hasViewport = /<meta[^>]+name=["']viewport["']/i.test(html);
const start = fetch.headers?.['request-duration'] || 0;
const responseTimeMs = fetch.timings?.total || (statusCode ? 1500 : 9999);

const issues = [];
let points = 0;

if (mobile != null && mobile < 50) { issues.push(`Very slow mobile (${mobile})`); points += 35; }
else if (mobile != null && mobile < 70) { issues.push(`Slow mobile (${mobile})`); points += 20; }
if (desktop != null && desktop < 60) { issues.push(`Slow desktop (${desktop})`); points += 15; }
if (!hasHttps) { issues.push('No HTTPS'); points += 25; }
if (!hasViewport && html) { issues.push('No mobile viewport'); points += 25; }
if (statusCode >= 400 || !html) { issues.push('Site error or unreachable'); points += 30; }
if (/wix\.com|wixsite\.com/i.test(html)) { issues.push('Wix builder'); points += 5; }
if (/squarespace\.com/i.test(html)) { issues.push('Squarespace'); points += 5; }

const reviews = parseInt(prospect.review_count, 10) || 0;
if (reviews >= 10 && points >= 15) {
  issues.push('Established on Maps, site undersells them');
  points += 10;
}

let review_priority = 'skip';
if (points >= 45) review_priority = 'high';
else if (points >= 25) review_priority = 'medium';
else if (points >= 12) review_priority = 'low';

return [{
  json: {
    place_id: prospect.place_id,
    business_name: prospect.business_name,
    address: prospect.address,
    phone: prospect.phone,
    website: prospect.website,
    google_maps_url: prospect.google_maps_url,
    category: prospect.category,
    city: prospect.city,
    region: prospect.region,
    google_rating: prospect.google_rating,
    review_count: prospect.review_count,
    mobile_pagespeed: mobile ?? '',
    desktop_pagespeed: desktop ?? '',
    has_https: hasHttps,
    has_viewport: hasViewport,
    response_time_ms: responseTimeMs,
    site_issues: [...new Set(issues)].join('; '),
    review_priority,
    review_status: 'new',
    discovered_at: new Date().toISOString(),
    notes: ''
  }
}];

const first = $('Build Search Queue').first().json;
return [{
  json: {
    key: 'city_index',
    value: String(first.next_city_index ?? 0)
  }
}, {
  json: {
    key: 'category_index',
    value: String(first.next_category_index ?? 0)
  }
}, {
  json: {
    key: 'last_run',
    value: new Date().toISOString()
  }
}];
